//! `fixtures/split/i4/i4_cases.json` (generated by its reviewed Python
//! statement of the contract) is the independent expectation.
use super::*;
use serde_json::Value;

const CASES: &str = include_str!("../../../../fixtures/split/i4/i4_cases.json");

fn fixture() -> Value {
    serde_json::from_str(CASES).expect("I4 fixture is JSON")
}

fn cases<'a>(fixture: &'a Value, key: &str) -> &'a [Value] {
    let cases = fixture[key].as_array().expect("case list");
    assert!(!cases.is_empty(), "{key}: zero selected cases is a failure");
    cases
}

fn outcome<T: Serialize>(result: Result<T, Refusal>, text: &str) -> String {
    match result {
        Ok(value) => {
            assert_eq!(
                canonical(&value),
                text.as_bytes(),
                "accepted bytes must be canonical"
            );
            "ok".into()
        }
        Err(refusal) => refusal.code().into(),
    }
}

#[test]
fn limits_match_the_contract() {
    let limits = &fixture()["limits"];
    assert_eq!(limits["pointer"], MAX_POINTER_BYTES as u64);
    assert_eq!(limits["record"], MAX_RECORD_BYTES as u64);
    assert_eq!(limits["setup_operation"], MAX_SETUP_OPERATION_BYTES as u64);
    assert_eq!(
        limits["operation_lifetime_ms"],
        MAX_SETUP_OPERATION_LIFETIME_MS
    );
}

#[test]
fn pointers_decode_as_reviewed() {
    let fixture = fixture();
    for case in cases(&fixture, "pointers") {
        let text = case["text"].as_str().unwrap();
        let observed = outcome(InstallPointer::decode(text.as_bytes()), text);
        assert_eq!(
            observed,
            case["expect"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn records_decode_against_their_pointer_as_reviewed() {
    let fixture = fixture();
    for case in cases(&fixture, "records") {
        let pointer_text = case["pointer"].as_str().unwrap();
        let pointer = InstallPointer::decode(pointer_text.as_bytes())
            .unwrap_or_else(|refusal| panic!("{}: pointer {refusal:?}", case["name"]));
        let text = case["text"].as_str().unwrap();
        let observed = outcome(InstallRecord::decode(text.as_bytes(), &pointer), text);
        assert_eq!(
            observed,
            case["expect"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn setup_operations_decode_with_the_injected_clock_as_reviewed() {
    let fixture = fixture();
    for case in cases(&fixture, "operations") {
        let text = case["text"].as_str().unwrap();
        let now = case["now_unix_ms"].as_u64().unwrap();
        let observed = outcome(SetupOperation::decode(text.as_bytes(), now), text);
        assert_eq!(
            observed,
            case["expect"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn setup_phases_are_ordered_as_reviewed() {
    let fixture = fixture();
    let expected: Vec<String> = cases(&fixture, "phases")
        .iter()
        .map(|phase| phase.as_str().unwrap().to_owned())
        .collect();
    let all = [
        SetupPhase::Locked,
        SetupPhase::PredecessorsRetired,
        SetupPhase::ServiceDrained,
        SetupPhase::Placed,
        SetupPhase::RecordWritten,
        SetupPhase::PointerWritten,
        SetupPhase::LoginRegistered,
        SetupPhase::LoginFailed,
        SetupPhase::LoginUnsupported,
        SetupPhase::TrustApplied,
        SetupPhase::TrustDeclined,
        SetupPhase::TrustUnsupported,
        SetupPhase::Started,
        SetupPhase::Healthy,
        SetupPhase::LoginUnregistered,
        SetupPhase::TrustRemoved,
        SetupPhase::PointerRemoved,
        SetupPhase::RecordRemoved,
        SetupPhase::DataPurged,
        SetupPhase::Complete,
    ];
    let observed: Vec<String> = all
        .iter()
        .map(|phase| {
            serde_json::to_value(phase)
                .unwrap()
                .as_str()
                .unwrap()
                .to_owned()
        })
        .collect();
    assert_eq!(observed, expected);
    assert!(all.windows(2).all(|pair| pair[0] < pair[1]));
}

#[test]
fn replacement_notices_decode_with_the_injected_clock_as_reviewed() {
    let fixture = fixture();
    let limits = &fixture["limits"];
    assert_eq!(
        limits["replacement_notice"],
        MAX_REPLACEMENT_NOTICE_BYTES as u64
    );
    assert_eq!(
        limits["replacement_notice_lifetime_ms"],
        MAX_REPLACEMENT_NOTICE_LIFETIME_MS
    );
    for case in cases(&fixture, "replacement_notices") {
        let text = case["text"].as_str().unwrap();
        let now = case["now_unix_ms"].as_u64().unwrap();
        let observed = outcome(ReplacementNotice::decode(text.as_bytes(), now), text);
        assert_eq!(
            observed,
            case["expect"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn start_requests_decode_with_the_injected_clock_as_reviewed() {
    let fixture = fixture();
    let limits = &fixture["limits"];
    assert_eq!(limits["start_request"], MAX_START_REQUEST_BYTES as u64);
    assert_eq!(
        limits["start_request_lifetime_ms"],
        MAX_START_REQUEST_LIFETIME_MS
    );
    for case in cases(&fixture, "start_requests") {
        let text = case["text"].as_str().unwrap();
        let nonce: Incarnation = case["nonce"].as_str().unwrap().parse().unwrap();
        let now = case["now_unix_ms"].as_u64().unwrap();
        let observed = outcome(StartRequest::decode(text.as_bytes(), nonce, now), text);
        assert_eq!(
            observed,
            case["expect"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn setup_receipts_decode_as_reviewed() {
    let fixture = fixture();
    for case in cases(&fixture, "receipts") {
        let text = case["text"].as_str().unwrap();
        let observed = match SetupReceipt::decode(text.as_bytes()) {
            Ok(receipt) => {
                assert_eq!(canonical(&receipt), text.as_bytes(), "{}", case["name"]);
                "ok".to_owned()
            }
            Err(refusal) => refusal.code().to_owned(),
        };
        assert_eq!(
            observed,
            case["expect"].as_str().unwrap(),
            "{}",
            case["name"]
        );
    }
}
